import random

def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    my = [h[0] for h in history]
    op = [h[1] for h in history]
    total_op_c = op.count('C')
    total_op_d = n - total_op_c
    last_op = op[-1]
    last_my = my[-1]

    if n == 1:
        return 'C' if last_op == 'C' else 'D'

    def run_len(seq, val):
        k = 0
        for a in reversed(seq):
            if a == val:
                k += 1
            else:
                break
        return k

    op_def_run = run_len(op, 'D')
    op_c_run = run_len(op, 'C')
    my_def_run = run_len(my, 'D')
    my_c_run = run_len(my, 'C')

    recent_len = 12 if n >= 12 else n
    recent = op[-recent_len:]
    recent_c = recent.count('C')
    recent_d = recent_len - recent_c

    if n >= 20:
        mid = n // 2
        early_c = op[:mid].count('C') / mid
        late_c = op[mid:].count('C') / max(1, n - mid)
    else:
        early_c = total_op_c / n
        late_c = early_c

    # Strongly cooperative opponent: ride the cooperation, only exploit very late.
    if total_op_d == 0:
        if n >= 96:
            return 'D'
        if n >= 88 and n % 5 == 0:
            return 'D'
        if n >= 60 and n % 13 == 0 and my_c_run >= 8:
            return 'D'
        return 'C'

    # Strongly defective opponent: mostly defend, rare probes.
    if total_op_c <= 1:
        if n % 25 == 0:
            return 'C'
        return 'D'

    # Long opponent defection streak: punish hard, break free rarely.
    if op_def_run >= 4:
        if op_def_run >= 7:
            if n % 9 == 0:
                return 'C'
            return 'D'
        if rng.random() < 0.12:
            return 'C'
        return 'D'

    # Opponent just defected after cooperating: retaliate, but be willing to forgive.
    if last_op == 'D':
        if total_op_d * 3 > n:
            return 'D'
        if recent_d >= 5:
            return 'D'
        if op_def_run >= 2:
            return 'D'
        # Isolated defection from a cooperative opponent: mostly forgive.
        if total_op_c * 4 >= n * 3 and late_c >= 0.55:
            if rng.random() < 0.35:
                return 'D'
            return 'C'
        if rng.random() < 0.5:
            return 'D'
        return 'C'

    # Opponent cooperated.
    # If we were punishing and they cooperated, resume cooperation but don't be a sucker.
    if my_def_run >= 2:
        if total_op_d * 2 > n:
            if rng.random() < 0.5:
                return 'D'
            return 'C'
        return 'C'

    # Opponent increasingly defecting: shift to defense.
    if n >= 20 and late_c < early_c - 0.2 and recent_d >= 3:
        return 'D'

    # Very defective profile: defect more.
    if total_op_d * 5 > n * 3:
        if rng.random() < 0.55:
            return 'D'
        return 'C'

    # Moderately defective: cautious cooperation with some punishment.
    if total_op_d * 3 > n:
        if recent_d >= 3:
            return 'D'
        if rng.random() < 0.25:
            return 'D'
        return 'C'

    # Mostly cooperative opponent. Occasionally probe if they aren't perfectly clean.
    if total_op_d >= 1:
        if n >= 10 and my_c_run >= 6 and rng.random() < 0.06:
            return 'D'

    # End-game exploitation of cooperative opponents.
    if n >= 90:
        remaining = 100 - n
        if total_op_d <= 4:
            if remaining <= 2:
                return 'D'
            if remaining <= 5 and rng.random() < 0.35:
                return 'D'

    return 'C'
